		if (e.self:GetX() > -110 or e.self:GetY() > -107) then
			e.self:GotoBind();
			e.self:WipeHateList();
			e.self:CastSpell(3230,e.self:GetID()); -- Spell: Balance of the Nameless
		else
			eq.set_timer("OOBcheck", 6 * 1000);
		end
	end
end

